// AUTO-GENERATED by packages/contracts/codegen/emit-wire-ts.ts — do not edit.
/** Frontend tracking event raised by the Shopify Pixel SDK (and other future pixel platforms). Drives funnel + abandoned-cart attribution. */
export enum PixelEventType {
	PAGE_VIEWED = 'PAGE_VIEWED',
	PRODUCT_VIEWED = 'PRODUCT_VIEWED',
	PRODUCT_ADDED_TO_CART = 'PRODUCT_ADDED_TO_CART',
	PRODUCT_REMOVED_FROM_CART = 'PRODUCT_REMOVED_FROM_CART',
	CART_VIEWED = 'CART_VIEWED',
	CHECKOUT_STARTED = 'CHECKOUT_STARTED',
	CHECKOUT_CONTACT_INFO_SUBMITTED = 'CHECKOUT_CONTACT_INFO_SUBMITTED',
	CHECKOUT_COMPLETED = 'CHECKOUT_COMPLETED',
}

import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import { TenancyScope, PixelEventType } from '@bk-dash/contracts-typescript/wire/enums'
import { MetricSchema, TallySchema } from '../../shared/schemas'
import { faker, mockMetric } from '../../shared/testing/mock'

// ---------------------------------------------------------------------------
// Input — `tenancyScope` is input-only (selects the store set; output shape is
// identical). storeId/storeIds from ctx; productIds optional filter.
// ---------------------------------------------------------------------------
export const GetPixelFunnelInputSchema = z.object({
	tenancyScope: z.enum(TenancyScope),
	storeId: z.uuid(), // ← ctx.session.storeId      (SINGLE_STORE)
	storeIds: z.array(z.uuid()), // ← ctx.membership.storeIds  (MULTI_STORE)
	startDate: z.date(),
	endDate: z.date(),
	productIds: z.array(z.uuid()).optional(),
})

// ---------------------------------------------------------------------------
// Output — single flat funnel (summed across the selected stores). Pure counts.
// steps = unique sessions per stage (Metric); rate derived FE (value / base).
// carts = abandoned carts Tally (count + lost value).
// ---------------------------------------------------------------------------
export const GetPixelFunnelOutputSchema = z.object({
	hasPixel: z.boolean(),
	base: MetricSchema,
	steps: z.enumRecord(PixelEventType, MetricSchema),
	conversionRate: MetricSchema,
	carts: TallySchema,
})

const recordOf = <T extends Record<string, string>, V>(enumObject: T, fn: () => V): Record<T[keyof T], V> =>
	Object.fromEntries(Object.values(enumObject).map(v => [v, fn()])) as Record<T[keyof T], V>

const seedFrom = (parts: string[]): number => {
	const s = parts.join('|')
	let h = 0
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0
	return Math.abs(h) || 1
}

/**
 * `GetPixelFunnel` — pixel funnel for the dashboard FunnelSection.
 *
 * FAKER body, REAL contract. `tenancyScope` selects the store set to query
 * (SINGLE = session store, MULTI = membership stores), summed into one funnel.
 * Real swap: two `PixelEventReadRepository.aggregateFunnelStages(...)` calls
 * (current + prior period) behind this same interface.
 */
@injectable()
export class GetPixelFunnel extends Handler<typeof GetPixelFunnelInputSchema, typeof GetPixelFunnelOutputSchema> {
	readonly name = 'get_pixel_funnel' as const
	readonly inputSchema = GetPixelFunnelInputSchema
	readonly outputSchema = GetPixelFunnelOutputSchema

	protected async handle(input: this['input']): Promise<this['output']> {
		const storeIds = input.tenancyScope === TenancyScope.MULTI_STORE ? input.storeIds : [input.storeId]
		faker.seed(seedFrom([...storeIds, input.startDate.toISOString(), input.endDate.toISOString(), ...(input.productIds ?? [])]))

		return {
			hasPixel: true,
			base: mockMetric(),
			steps: recordOf(PixelEventType, mockMetric),
			conversionRate: mockMetric(),
			carts: { count: mockMetric(), value: mockMetric() },
		}
	}
}

import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { GetPixelFunnel, GetPixelFunnelInputSchema, GetPixelFunnelOutputSchema } from '../usecases/GetPixelFunnel'

export const GetPixelFunnelControllerInputSchema = z.object({
	ctx: z.object({
		session: z.object({ storeId: z.uuid() }),
		membership: z.object({ storeIds: z.array(z.uuid()) }),
	}),
	query: GetPixelFunnelInputSchema.omit({ storeId: true, storeIds: true, startDate: true, endDate: true, productIds: true }).extend({
		startDate: z.stringToDate(),
		endDate: z.stringToDate(),
		productIds: z.stringToArray(z.uuid()).optional(),
	}),
})

export const GetPixelFunnelControllerOutputSchema = GetPixelFunnelOutputSchema

@injectable()
export class GetPixelFunnelController extends Controller<
	typeof GetPixelFunnelControllerInputSchema,
	typeof GetPixelFunnelControllerOutputSchema
> {
	readonly path = '/funnel'
	readonly method = 'get' as const
	readonly description = 'Pixel funnel for the dashboard (unique sessions per stage, conversion rate, abandoned carts)'
	readonly inputSchema = GetPixelFunnelControllerInputSchema
	readonly outputSchema = GetPixelFunnelControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private query: GetPixelFunnel) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.query.execute({
			tenancyScope: request.query.tenancyScope,
			storeId: request.ctx.session.storeId,
			storeIds: request.ctx.membership.storeIds,
			startDate: request.query.startDate,
			endDate: request.query.endDate,
			productIds: request.query.productIds,
		})
		return { status: HttpStatusCode.OK, data }
	}
}

