import { BaseValueObject } from '@bk-dash/core-typescript'
import { z } from '@bk-dash/core-typescript'

import Z from 'zod'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const MonetaryAmountSchema = z.object({
	amountCents: z.number().int().nonnegative(),
	currency: z.enum(CurrencyCode),
})

/**
 * Signed variant for computed reporting figures (gross margin, profit, …) that
 * can legitimately be negative. NOT a stored MonetaryAmount value object — it's
 * the read-side shape for analytics outputs, so it drops the `.nonnegative()`.
 */
export const SignedMonetaryAmountSchema = z.object({
	amountCents: z.number().int(),
	currency: z.enum(CurrencyCode),
})

export class MonetaryAmount extends BaseValueObject<typeof MonetaryAmountSchema> {
	static override schema = MonetaryAmountSchema

	equals(other: MonetaryAmount): boolean {
		return this.amountCents === other.amountCents && this.currency === other.currency
	}
}

export interface MonetaryAmount extends Z.infer<typeof MonetaryAmountSchema> {}

/**
 * Generic, domain-agnostic KPI atoms shared across BFF query use cases.
 * Context-specific shapes (Stat, breakdowns, dashboard details, …) live in the
 * owning context's `schemas/` folder, NOT here.
 */
import { z } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

/** Partial record of ISO-4217 currency → raw numeric value (not cents). A store
 *  reports only the currencies it transacts in, not the full ISO set. */
export const CurrencyAmountSchema = z.partialRecord(z.enum(CurrencyCode), z.number())

/** KPI atom: current value + period-over-period delta fraction (null = no prior period). */
export const MetricSchema = z.object({
	value: z.number(),
	deltaPct: z.number().nullable(),
})

/** Multi-currency Metric (consolidated aggregates that cross currencies). */
export const CurrencyMetricSchema = z.object({
	value: CurrencyAmountSchema,
	deltaPct: z.number().nullable(),
})

/** Generic count + monetary-value atom, each with its own delta. */
export const TallySchema = z.object({
	count: MetricSchema,
	value: MetricSchema,
})

/** Consolidated multi-currency variant: value is a CurrencyMetric. */
export const ConsolidatedTallySchema = z.object({
	count: MetricSchema,
	value: CurrencyMetricSchema,
})

/** Decomposition helper: `{ total, segments: { [enumMember]: Metric } }` (enum-keyed). */
export function segmented<T extends Record<string, string>>(enumObject: T) {
	return z.object({
		total: MetricSchema,
		segments: z.enumRecord(enumObject, MetricSchema),
	})
}

import { z } from '@bk-dash/core-typescript/schema'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire'

export const MonetaryByCurrencySchema = z.record(z.enum(CurrencyCode), z.number().int())

import { AggregateRoot, BaseError, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import type { DomainErrors } from '../errors'

// IANA timezone shape: Region/City or Region/Sub/City; plus UTC alias.
const IANA_TIMEZONE_RE = /^[A-Za-z_+-]+\/[A-Za-z_+-]+(?:\/[A-Za-z_+-]+)?$|^UTC$/

export const StoreSchema = z.object({
	name: z.string().trim().min(1).max(120),
	pictureUrl: z.url().optional(),
	email: z
		.string()
		.email({ error: 'INVALID_EMAIL' as DomainErrors })
		.optional(),
	phoneNumber: z.string().min(5).max(40).optional(),
	reportingCurrency: z.enum(CurrencyCode),
	timezone: z.string().regex(IANA_TIMEZONE_RE, { error: 'INVALID_TIMEZONE' as DomainErrors }),
	isDisabled: z.boolean().default(false),
	disabledReason: z.string().optional(),
	showStoreNameInNotifications: z.boolean().default(true),
	// The Subscription (billing BC) this store consumes a slot from.
	// Nullable: pre-release no-backfill; new stores always set it.
	// Reassignable via ChangeStoreSubscription.
	subscriptionId: z.uuid().nullable().default(null),
})

export type StoreProps = Z.infer<typeof StoreSchema>

export class Store extends AggregateRoot<typeof StoreSchema> {
	static override schema = StoreSchema

	static create(data: {
		name: string
		reportingCurrency: CurrencyCode
		timezone: string
		pictureUrl?: string
		email?: string
		phoneNumber?: string
		subscriptionId?: string | null
	}): Store {
		return new Store({
			name: data.name,
			reportingCurrency: data.reportingCurrency,
			timezone: data.timezone,
			pictureUrl: data.pictureUrl,
			email: data.email,
			phoneNumber: data.phoneNumber,
			isDisabled: false,
			disabledReason: undefined,
			showStoreNameInNotifications: true,
			subscriptionId: data.subscriptionId ?? null,
		})
	}

	updateSettings(input: { name?: string; pictureUrl?: string; email?: string; phoneNumber?: string }): void {
		for (const k of ['name', 'pictureUrl', 'email', 'phoneNumber'] as const) {
			if (input[k] !== undefined && this[k] !== input[k]) {
				;(this as any)[k] = input[k]
			}
		}
		this.validate()
	}

	updatePreferences(
		input: {
			reportingCurrency?: CurrencyCode
			timezone?: string
			showStoreNameInNotifications?: boolean
		},
		ctx: { hasOrders: boolean },
	): void {
		if (input.reportingCurrency !== undefined && input.reportingCurrency !== this.reportingCurrency) {
			// Once a Store has any canonical order, the reporting currency is
			// locked — switching would invalidate every existing analytics
			// rollup (spec §"REPORTING_CURRENCY_LOCKED" invariant).
			if (ctx.hasOrders) throw new BaseError<DomainErrors>('REPORTING_CURRENCY_LOCKED')
			this.reportingCurrency = input.reportingCurrency
		}
		if (input.timezone !== undefined && input.timezone !== this.timezone) {
			this.timezone = input.timezone
		}
		if (input.showStoreNameInNotifications !== undefined && input.showStoreNameInNotifications !== this.showStoreNameInNotifications) {
			this.showStoreNameInNotifications = input.showStoreNameInNotifications
		}

		this.validate()
	}

	disable(reason?: string): void {
		if (this.isDisabled) throw new BaseError<DomainErrors>('STORE_ALREADY_DISABLED')
		this.isDisabled = true
		this.disabledReason = reason
	}

	enable(): void {
		if (!this.isDisabled) throw new BaseError<DomainErrors>('STORE_NOT_DISABLED')
		this.isDisabled = false
		this.disabledReason = undefined
	}

	/** Reassign this store to a different subscription (ChangeStoreSubscription). */
	changeSubscription(subscriptionId: string): void {
		this.subscriptionId = subscriptionId
		this.validate()
	}
}

export interface Store extends StoreProps {}

import Z from 'zod'
import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import { ProductCostType, CurrencyCode, Country } from '@bk-dash/contracts-typescript/wire/enums'
import { Timeline } from '../../shared/objects'
import { ProductCostOption, ProductCostOptionSchema } from '../objects/ProductCostOption'
import { ProductCostOptionItem, ProductCostOptionItemSchema } from '../objects/ProductCostOptionItem'
import type { CatalogApplicationErrors } from '../errors'

// `ProductCostOption` / `ProductCostOptionItem` are aggregate-internal value
// objects (live in `../objects`). Re-exported so existing importers keep their
// `../entities/ProductCost` path.
export { ProductCostOption, ProductCostOptionSchema, ProductCostOptionItem, ProductCostOptionItemSchema }

export const ProductCostSchema = z.object({
	storeId: z.instance(Id),
	storeIntegrationId: z.instance(Id),
	/** Null when scoped to a kit (multi-variant bundle priced together). */
	productId: z.instance(Id).nullable(),
	costType: z.enum(ProductCostType),
	options: z.array(z.instance(ProductCostOption)),
	deletedAt: z.date().nullable(),
})

export type ProductCostProps = Z.infer<typeof ProductCostSchema>

// ─── Input schemas (no computed fields, used by use cases / controllers) ──────

// Derived from ProductCostOptionItemSchema: strips computed `id` + `variantsHash`,
// unwraps z.instance(Id) → string and z.instance(MonetaryAmount) → { amountCents, currency }.
// No casts needed — .input() returns a properly typed ZodObject; .omit() chains directly.
export const ProductCostOptionItemInputSchema = ProductCostOptionItemSchema.input().omit({ id: true, variantsHash: true })

export const ProductCostOptionInputSchema = z.object({
	currency: z.enum(CurrencyCode),
	country: z.enum(Country).optional(),
	startDate: z.iso.date(),
	endDate: z.iso.date().optional(),
	items: z.array(ProductCostOptionItemInputSchema).min(1),
})

export type ProductCostOptionInput = Z.infer<typeof ProductCostOptionInputSchema>

/**
 * Deterministic hash of a sorted variant-ID set.
 * In production this should use crypto.createHash; for the Mock layer a
 * stable string sort + join is sufficient and produces consistent overlap
 * detection without the crypto dep at this module's load time.
 */
function hashVariantIds(variantIds: string[]): string {
	return [...variantIds].sort().join('|')
}

function buildItems(items: ProductCostOptionInput['items']) {
	return items.map(item => ({
		id: crypto.randomUUID(),
		variantIds: item.variantIds,
		quantity: item.quantity,
		quantityModifier: item.quantityModifier,
		unitCost: item.unitCost,
		variantsHash: hashVariantIds(item.variantIds),
	}))
}

interface PaintedOptionValue {
	items: ReturnType<typeof buildItems>
	startDate: Date
	endDate: Date | null
}
interface PaintedOption {
	id: string
	currency: CurrencyCode
	country?: Country
	values: PaintedOptionValue[]
}

/** Group input options by (currency, country); paint each value onto that key's Timeline. */
function groupAndPaint(inputs: ProductCostOptionInput[]): PaintedOption[] {
	const byKey = new Map<string, PaintedOption>()
	for (const opt of inputs) {
		const key = `${opt.currency}|${opt.country ?? ''}`
		const value: PaintedOptionValue = {
			items: buildItems(opt.items),
			startDate: new Date(opt.startDate),
			endDate: opt.endDate ? new Date(opt.endDate) : null,
		}
		const entry = byKey.get(key)
		if (entry) entry.values = [...new Timeline(entry.values).place(value).entries]
		else byKey.set(key, { id: crypto.randomUUID(), currency: opt.currency, country: opt.country, values: [value] })
	}
	return [...byKey.values()]
}

/**
 * `ProductCost` aggregate per spec § 4 BC5.
 *
 * One `ProductCost` represents a merchant's cost configuration for a
 * (storeIntegration × product?) scope. It holds one or more
 * `ProductCostOption`s — each scoped by currency and country — which in turn
 * hold a `values` Timeline of `{ items }` (the per-variant unit costs that
 * change over time).
 *
 * - Invariant: each option's `values` timeline is non-overlapping
 *   (Timeline-enforced); at most one option per (currency, country).
 * - Soft-delete: `deletedAt` is set by `delete()`; the row is preserved for
 *   historical COGS attribution.
 * - Scoping keys (storeIntegrationId, productId) are immutable after creation.
 */
export class ProductCost extends AggregateRoot<typeof ProductCostSchema> {
	static override schema = ProductCostSchema

	static create(data: {
		storeId: string
		storeIntegrationId: string
		productId: string | null
		costType: ProductCostType
		options: ProductCostOptionInput[]
	}): ProductCost {
		// Group by (currency, country) and paint each value onto the option's Timeline.
		// Then validate each painted option through ProductCostOptionSchema.
		const options = groupAndPaint(data.options)

		for (const opt of options) {
			const r = ProductCostOptionSchema.safeParse(opt)
			if (!r.success) throw new BaseError(r.error.issues[0]!.message)
		}

		return new ProductCost({
			id: crypto.randomUUID(),
			storeId: data.storeId,
			storeIntegrationId: data.storeIntegrationId,
			productId: data.productId,
			costType: data.costType,
			options,
			deletedAt: null,
		})
	}

	/** Updates mutable fields — the full options set. */
	update(data: { options?: ProductCostOptionInput[] }): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		if (data.options !== undefined) {
			const options = groupAndPaint(data.options)
			for (const opt of options) {
				const r = ProductCostOptionSchema.safeParse(opt)
				if (!r.success) throw new BaseError(r.error.issues[0]!.message)
			}
			// Materialize the plain options into ProductCostOption value objects
			// through the aggregate's own field schema — no `new` in the body.
			this.options = ProductCostSchema.shape.options.parse(options)
		}
		this.validate()
	}

	/** Soft-delete. Preserved for historical COGS attribution. */
	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface ProductCost extends ProductCostProps {}

import { pgSchema, uuid, text, timestamp, boolean, integer, bigint, jsonb, index, uniqueIndex, primaryKey } from 'drizzle-orm/pg-core'

/**
 * `sales` is BK Dash's BC4 Sales schema.
 *
 * The canonical `orders` table is **Go-owned**: go-worker writes via
 * `UPSERT … ON CONFLICT (platform, external_id) DO UPDATE` after every
 * webhook + backfill page. TS consumers (Sales, Notifications,
 * Analytics) only read.
 *
 * Merchant edits land in the separate `order_overrides` aggregate
 * (TS-owned write-side, in iter 42a-ii) which joins on `order_id` at
 * query time — keeping provider data immutable in `orders` while still
 * letting merchants correct totals/method/etc. without rewriting source.
 */
export const salesSchema = pgSchema('sales')

export const orders = salesSchema.table(
	'orders',
	{
		// Deterministic UUIDv5 derived from (platform, external_id) so both
		// go-worker and the TS API resolve the same internal id without a
		// database lookup. The namespace constant lives in
		// packages/api/{go,typescript}/core/objects/ and stays byte-for-byte
		// identical across services.
		id: uuid('id').primaryKey(),

		// Tenant scoping. storeIntegrationExternalId is the provider-side
		// handle (e.g. shop domain) and the canonical tenancy/query anchor:
		// it survives credential rotation, unlike the storeIntegrationId
		// connection row (dropped). The owning store is reached via
		// catalog.store_integrations.
		storeIntegrationExternalId: text('store_integration_external_id').notNull(),

		// Provider identity.
		platform: text('platform').notNull(),
		externalId: text('external_id').notNull(),
		externalCreatedAt: timestamp('external_created_at', { withTimezone: true }).notNull(),

		// Customer + shipping snapshots (jsonb because shapes vary per
		// provider and BK Dash doesn't normalize address into columns).
		description: text('description'),
		customerEmail: text('customer_email'),
		customerName: text('customer_name'),
		customerPhone: text('customer_phone'),
		shippingAddress: jsonb('shipping_address'),

		// Monetary totals — bigint(cents) + ISO-4217 currency. Native +
		// presentment + settlement preserved separately so FX is applied at
		// query time in the consumer's reportingCurrency.
		subtotalCents: bigint('subtotal_cents', { mode: 'bigint' }).notNull(),
		discountTotalCents: bigint('discount_total_cents', { mode: 'bigint' }).notNull(),
		shippingTotalCents: bigint('shipping_total_cents', { mode: 'bigint' }).notNull(),
		taxTotalCents: bigint('tax_total_cents', { mode: 'bigint' }).notNull(),
		totalCents: bigint('total_cents', { mode: 'bigint' }).notNull(),
		totalCurrency: text('total_currency').notNull(),

		presentmentTotalCents: bigint('presentment_total_cents', { mode: 'bigint' }),
		presentmentCurrency: text('presentment_currency'),
		settlementTotalCents: bigint('settlement_total_cents', { mode: 'bigint' }),
		settlementCurrency: text('settlement_currency'),

		// Payment classification.
		paymentStatus: text('payment_status').notNull(),
		paymentMethod: text('payment_method').notNull(),
		paymentGateway: text('payment_gateway').notNull(),

		// Line items + transactions stored as jsonb arrays. Indexed for
		// per-aggregate reads (a query asking for one order returns the
		// full document in one round-trip).
		lines: jsonb('lines').notNull(),
		transactions: jsonb('transactions').notNull(),

		// Cart linkage + attribution.
		cartToken: text('cart_token'),
		utm: jsonb('utm'),

		// Lifecycle flags.
		isDraft: boolean('is_draft').notNull().default(false),
		isManual: boolean('is_manual').notNull().default(false),

		// Audit / optimistic concurrency.
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Provider uniqueness. The UPSERT discriminator. Drives the
		// `is_new = (xmax = 0)` first-write detection on RETURNING.
		platformExternalIdUnq: uniqueIndex('orders_platform_external_id_unq').on(t.platform, t.externalId),
		// Tenant-scoped reads filter by storeIntegrationExternalId (the
		// stable provider-side handle / tenancy anchor).
		storeIntegrationExternalIdx: index('orders_store_integration_external_id_idx').on(t.storeIntegrationExternalId),
		// Time-series reads order DESC for "latest orders" lists.
		externalCreatedAtIdx: index('orders_external_created_at_idx').on(t.externalCreatedAt),
	}),
)

