import { pgSchema, uuid, text, timestamp, integer, boolean, index, uniqueIndex, primaryKey } from 'drizzle-orm/pg-core'

/**
 * `tenancy` is BK Dash's BC2 Tenancy schema.
 *
 * A Store is BK Dash's workspace — the unit of multi-tenancy. Every
 * canonical row (orders, products, campaigns, …) is scoped to a
 * `store_id`. A User may belong to many Stores via
 * `store_memberships`, with a Role (OWNER | ADMIN | MEMBER) per
 * membership.
 *
 * Tables:
 *   - `stores`             — TS-owned workspace
 *   - `store_memberships`  — many-to-many with role per pair
 *   - `store_invitations`  — pending invites (email + token + expiry)
 */
export const tenancySchema = pgSchema('tenancy')

export const stores = tenancySchema.table(
	'stores',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		// Human-readable workspace name (e.g. "Acme Co"). Mutable.
		name: text('name').notNull(),

		// ISO-4217 currency every analytics rollup converts to when
		// computing a single number. Per spec: **immutable after the
		// first canonical row is ingested** (REPORTING_CURRENCY_LOCKED
		// invariant). Enforced at app level (use case checks before
		// UPDATE).
		reportingCurrency: text('reporting_currency').notNull(),

		// IANA timezone (e.g. "America/Sao_Paulo"). Drives daily digest
		// scheduling + per-Store time bucketing in TimezoneMode.PER_STORE.
		timezone: text('timezone').notNull(),

		// Soft-disable flag. Cascade-quarantines ingest + queries across
		// downstream BCs (see spec §"Tenancy → … StoreDisabled" event).
		isDisabled: boolean('is_disabled').notNull().default(false),
		disabledReason: text('disabled_reason'),

		// Per spec §4 BC2 + §7.2 T09 (StorePreferencesSettings): when
		// false, notifications hide the Store name for merchants who run
		// the BK Dash app across many stores and don't want each push
		// pre-pended with the source. Spec originally puts this on a
		// separate `StorePreferences` aggregate; we collapse it into
		// `stores` to keep the row count down (the split is a
		// use-case-level concern preserved by C13 UpdateStoreSettings vs
		// C14 UpdateStorePreferences operating on disjoint field sets).
		showStoreNameInNotifications: boolean('show_store_name_in_notifications').notNull().default(true),

		// The Subscription (billing BC) this store consumes a slot from.
		// Nullable: pre-release no-backfill; CreateStore always sets it for
		// new stores. Reassignable via ChangeStoreSubscription.
		subscriptionId: uuid('subscription_id'),

		// Audit / optimistic concurrency.
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Per-spec there's no global uniqueness on Store name — two
		// merchants can both call their store "Acme Co". Only the id is
		// canonical.
		isDisabledIdx: index('stores_is_disabled_idx').on(t.isDisabled),
		subscriptionIdx: index('stores_subscription_id_idx').on(t.subscriptionId),
	}),
)

/**
 * `store_memberships` — many-to-many between Users and Stores with a
 * Role per pair. Composite primary key (storeId, userId) — a User has
 * at most one membership per Store.
 *
 * Spec invariants enforced at use-case level (Drizzle can't express
 * them inline):
 *   - Every Store has ≥ 1 OWNER (CANNOT_REMOVE_LAST_OWNER + CANNOT_
 *     DEMOTE_LAST_OWNER errors guard this).
 *   - A user can't be added twice to the same Store (ALREADY_A_MEMBER
 *     — also guarded by the composite PK).
 */
export const storeMemberships = tenancySchema.table(
	'store_memberships',
	{
		storeId: uuid('store_id')
			.notNull()
			.references(() => stores.id, { onDelete: 'cascade' }),
		userId: uuid('user_id').notNull(),

		// Role enum (OWNER | ADMIN | MEMBER). Stored as text — keep the
		// enum value-list to Identity's spec-canonical TenancyRole (3
		// values), avoiding the pre-existing template `RoleType` enum
		// (OWNER/ADMIN/COLLABORATOR) that uses different values.
		role: text('role').notNull(),

		// Audit.
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),

