		compareAtPriceCents: bigint('compare_at_price_cents', { mode: 'bigint' }),

		// Provider inventory quantity. Sentinel-free — null = provider
		// doesn't track inventory for this variant.
		quantityAvailable: integer('quantity_available'),

		status: text('status').notNull(),
		isDefault: boolean('is_default').notNull().default(false),

		externalCreatedAt: timestamp('external_created_at', { withTimezone: true }).notNull(),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		platformExternalIdUnq: uniqueIndex('variants_platform_external_id_unq').on(t.platform, t.externalId),
		productIdx: index('variants_product_id_idx').on(t.productId),
		storeIntegrationIdx: index('variants_store_integration_id_idx').on(t.storeIntegrationId),
	}),
)

/**
 * `product_costs` is the merchant-owned cost aggregate per Store ×
 * Product. The header carries scope + type; the `product_cost_options`
 * child table carries the time-effective / per-country / per-variant
 * cost tiers (one option = one (currency, country?, dateRange) slice).
 *
 * Spec rule: at most one ProductCost per (storeId, productId). The
 * variant-level granularity is encoded in `product_cost_options.items`.
 */
export const productCosts = catalogSchema.table(
	'product_costs',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),
		// Scopes the cost row to the StoreIntegration that owns the
		// underlying product/variant ids. Required because the same
		// product can appear under multiple integrations (multi-channel
		// merchant) and merchant cost rules are typically per-channel.
		storeIntegrationId: uuid('store_integration_id').notNull(),
		// References catalog.products.id but no FK — products can be
		// re-synced (re-UPSERTed) without breaking the merchant's cost
		// data; we want costs to survive provider id changes. Nullable
		// for kit-scoped costs (multi-variant bundle priced together).
		productId: uuid('product_id'),

		// Discriminator from spec ProductCostType (SINGLE / MULTIPLE).
		// SINGLE = one cost across all variants; MULTIPLE = per-variant.
		costType: text('cost_type').notNull(),

		// Time-effective option array, stored inline as jsonb. Each
		// option carries: { id, currency, country?, startDate, endDate?,
		// items: [{id, variantIds, quantity, quantityModifier,
		// unitCost, variantsHash}] }.
		// Inlined (vs the original product_cost_options child table)
		// because reads always pull the full document; the child-table
		// shape required cascade writes + N+1 reads for no actual
		// normalization benefit.
		options: jsonb('options').notNull().default([]),

		// Soft-delete timestamp. List queries filter by `deleted_at IS NULL`.
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Partial unique — only enforce on live rows so a re-created cost
		// for the same (storeId, productId) after soft-delete doesn't
		// collide with the historical row.
		storeProductUnq: uniqueIndex('product_costs_store_product_unq').on(t.storeId, t.productId).where(sql`${t.deletedAt} IS NULL`),
		storeIdx: index('product_costs_store_id_idx').on(t.storeId),
		storeIntegrationIdx: index('product_costs_store_integration_id_idx').on(t.storeIntegrationId),
	}),
)

// `product_cost_options` removed iter 320 — options now stored inline
// as a jsonb column on `product_costs`. The child-table normalization
// added cascade write complexity for no read-side benefit (the
// aggregate is always read as a complete document).

import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { MarketingPlatform, AdSpendGroupBy, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import type { MarketingDomainErrors } from '../errors'

export const ManualMarketingExpenseBindingSchema = z.object({
	productId: z.string().optional(),
	variantId: z.string().optional(),
})

export const AdSpendManualSchema = z
	.object({
		storeId: z.instance(Id),
		adAccountExternalId: z.string().optional(),
		campaignExternalId: z.string().optional(),
		// Optional: MANUAL rows store null in DB; undefined here means no platform.
		platform: z.enum(MarketingPlatform).optional(),
		currency: z.enum(CurrencyCode),
		// Full ISO 8601 datetime strings required. Legacy date-only DB rows
		// ('2026-05-01') are normalised to datetime in toDomain before parse.
		// TODO: remove toDomain coercion after legacy date-only rows migrate.
		startDate: z.date(),
		endDate: z.date(),
		groupBy: z.enum(AdSpendGroupBy),
		spend: z.instance(MonetaryAmount),
		impressions: z.number().int().optional(),
		clicks: z.number().int().optional(),
		conversions: z.number().int().optional(),
		name: z.string().optional(),
		description: z.string().optional(),
		bindings: z.array(ManualMarketingExpenseBindingSchema).optional(),
		disabledAt: z.date().optional(),
	})
	.refine(data => data.startDate <= data.endDate, {
		error: 'INVALID_DATE_RANGE' as MarketingDomainErrors,
	})

export type AdSpendManualProps = Z.infer<typeof AdSpendManualSchema>

export class AdSpendManual extends AggregateRoot<typeof AdSpendManualSchema> {
	static override schema = AdSpendManualSchema

	static create(data: {
		storeId: string
		adAccountExternalId?: string
		campaignExternalId?: string
		platform?: MarketingPlatform
		currency: CurrencyCode
		startDate: Date
		endDate: Date
		spend: { amountCents: number; currency: CurrencyCode }
		impressions?: number
		clicks?: number
		conversions?: number
		name?: string
		description?: string
		bindings?: Array<{ productId?: string; variantId?: string }>
	}): AdSpendManual {
		// Named domain-error guard — schema .refine() fires at the schema
		// boundary (safeParse returns false) but BaseEntity maps schema
		// failures to INVALID_ENTITY. We throw the specific code here so
		// callers and tests can assert on INVALID_DATE_RANGE.
		if (data.startDate > data.endDate) {
			throw new BaseError<MarketingDomainErrors>('INVALID_DATE_RANGE', 'startDate must be before or equal to endDate')
		}
		return new AdSpendManual({
			storeId: data.storeId,
			adAccountExternalId: data.adAccountExternalId,
			campaignExternalId: data.campaignExternalId,
			platform: data.platform,
			currency: data.currency,
			startDate: data.startDate,
			endDate: data.endDate,
			groupBy: AdSpendGroupBy.DAILY,
			spend: data.spend,
			impressions: data.impressions,
			clicks: data.clicks,
			conversions: data.conversions,
			name: data.name,
			description: data.description,
			bindings: data.bindings,
		})
	}

	updateManual(patch: {
		name?: string
		description?: string
		startDate?: Date
		endDate?: Date
		spend?: { amountCents: number; currency: CurrencyCode }
		bindings?: Array<{ productId?: string; variantId?: string }>
	}): void {
		// Named domain-error guard — mirrors create() for the same reason.
		const effectiveStart = patch.startDate ?? this.startDate
		const effectiveEnd = patch.endDate ?? this.endDate
		if (effectiveStart > effectiveEnd) {
			throw new BaseError<MarketingDomainErrors>('INVALID_DATE_RANGE', 'startDate must be before or equal to endDate')
		}
		if (patch.name !== undefined) this.name = patch.name
		if (patch.description !== undefined) this.description = patch.description
		if (patch.startDate !== undefined) this.startDate = patch.startDate
		if (patch.endDate !== undefined) this.endDate = patch.endDate
		if (patch.spend !== undefined) this.spend = new MonetaryAmount(patch.spend)
		if (patch.bindings !== undefined) this.bindings = patch.bindings
	}
}

export interface AdSpendManual extends AdSpendManualProps {}

import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { type CurrencyCode, GoalType } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import type { AnalyticsDomainErrors } from '../errors'

export const GoalSchema = z.object({
	storeId: z.instance(Id),
	type: z.enum(GoalType),
	targetAmount: z.instance(MonetaryAmount).refine(m => m.amountCents > 0, {
		error: 'INVALID_AMOUNT' as AnalyticsDomainErrors,
	}),
	from: z.date(),
	to: z.date(),
})

export type GoalProps = Z.infer<typeof GoalSchema>

/**
 * `Goal` aggregate per spec § BC11 Analytics. Per-user, per-Store
 * revenue or profit target over a date window. Immutable scoping keys
 * after creation; only the target amount is mutable.
 */
export class Goal extends AggregateRoot<typeof GoalSchema> {
	static override schema = GoalSchema

	static create(data: {
		storeId: string
		type: GoalType
		targetAmount: { amountCents: number; currency: CurrencyCode }
		from: Date
		to: Date
	}): Goal {
		if (data.from > data.to) {
			throw new BaseError<AnalyticsDomainErrors>('INVALID_DATE_RANGE', 'from must be <= to')
		}
		return new Goal(data)
	}

	updateTarget(patch: { targetAmount?: { amountCents: number; currency: CurrencyCode }; from?: Date; to?: Date }): void {
		const effFrom = patch.from ?? this.from
		const effTo = patch.to ?? this.to
		if (effFrom > effTo) {
			throw new BaseError<AnalyticsDomainErrors>('INVALID_DATE_RANGE', 'from must be <= to')
		}
		if (patch.targetAmount !== undefined) {
			this.targetAmount = new MonetaryAmount(patch.targetAmount)
		}
		if (patch.from !== undefined) {
			this.from = patch.from
		}
		if (patch.to !== undefined) {
			this.to = patch.to
		}
		this.validate()
	}
}

export interface Goal extends GoalProps {}

import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import {
	OperationalCostCategory,
	OperationalCostFlow,
	OperationalCostPaymentStatus,
	OperationalCostRecurrency,
	type CurrencyCode,
} from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import type { FinanceDomainErrors } from '../errors'
import { countOccurrencesInRange, occurrenceWindow } from './recurrence'

export const StatusOverrideSchema = z.object({
	occurrenceDate: z.date(),
	status: z.enum(OperationalCostPaymentStatus),
})

export const OperationalCostSchema = z.object({
	storeId: z.instance(Id),
	category: z.enum(OperationalCostCategory),
	// Cash-flow direction: DEBIT = money out (a cost), CREDIT = money in.
	flow: z.enum(OperationalCostFlow),
	description: z.string().min(1).max(500),
	amount: z.instance(MonetaryAmount).refine(m => m.amountCents > 0, {
		error: 'INVALID_AMOUNT' as FinanceDomainErrors,
	}),
	recurrency: z.enum(OperationalCostRecurrency),
	startDate: z.date(),
	endDate: z.date().nullable(),
	// Sparse deviations from the default per-occurrence status — NOT the
	// full occurrence set. Occurrences are derived at runtime; this only
	// records the ones the merchant flipped away from DEFAULT_OCCURRENCE_STATUS.
	statusOverrides: z.array(StatusOverrideSchema).default([]),
	deletedAt: z.date().nullable(),
})

export type OperationalCostProps = Z.infer<typeof OperationalCostSchema>

export interface OperationalCostOccurrence {
	occurrenceDate: Date
	status: OperationalCostPaymentStatus
}

/**
 * `OperationalCost` aggregate per spec § BC8 Finance. Recurrent or
 * one-off business expense (rent, employee salary, software, etc).
 *
 * Occurrences are **derived at runtime** from `(recurrency, startDate,
 * endDate)` — never stored. Every derived occurrence carries
 * `DEFAULT_OCCURRENCE_STATUS` (PAID) unless `statusOverrides[]` records a
 * deviation for that date. Resolution is therefore **by exclusion**: the
 * full series minus the overridden dates, rather than summing stamped rows.
 *
 * Soft-deleted by `delete()`: row preserved so historical analytics
 * keep their context.
 */
export class OperationalCost extends AggregateRoot<typeof OperationalCostSchema> {
	static override schema = OperationalCostSchema

	/** Status every derived occurrence carries until a `statusOverride` says otherwise. */
	static readonly DEFAULT_OCCURRENCE_STATUS = OperationalCostPaymentStatus.PAID

	/** Cash-flow direction assumed when the caller doesn't specify one. */
	static readonly DEFAULT_FLOW = OperationalCostFlow.DEBIT

	static create(data: {
		storeId: string
		category: OperationalCostCategory
		flow?: OperationalCostFlow
		description: string
		amount: { amountCents: number; currency: CurrencyCode }
		recurrency: OperationalCostRecurrency
		startDate: Date
		endDate?: Date
	}): OperationalCost {
		if (data.endDate !== undefined && data.startDate > data.endDate) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'startDate must be <= endDate')
		}
		return new OperationalCost({
			storeId: data.storeId,
			category: data.category,
			flow: data.flow ?? OperationalCost.DEFAULT_FLOW,
			description: data.description,
			amount: data.amount,
			recurrency: data.recurrency,
			startDate: data.startDate,
			endDate: data.endDate ?? null,
			statusOverrides: [],
			deletedAt: null,
		})
	}

	update(patch: {
		category?: OperationalCostCategory
		flow?: OperationalCostFlow
		description?: string
		amount?: { amountCents: number; currency: CurrencyCode }
		recurrency?: OperationalCostRecurrency
		startDate?: Date
		endDate?: Date | null
	}): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot update a deleted OperationalCost')
		}
		const effectiveStart = patch.startDate ?? this.startDate
		const effectiveEnd = patch.endDate !== undefined ? patch.endDate : this.endDate
		if (effectiveEnd !== null && effectiveStart > effectiveEnd) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'startDate must be <= endDate')
		}
		if (patch.category !== undefined) {
			this.category = patch.category
		}
		if (patch.flow !== undefined) {
			this.flow = patch.flow
		}
		if (patch.description !== undefined) {
			this.description = patch.description
		}
		if (patch.amount !== undefined) {
			this.amount = new MonetaryAmount(patch.amount)
		}
		if (patch.recurrency !== undefined) {
			this.recurrency = patch.recurrency
		}
		if (patch.startDate !== undefined) {
			this.startDate = patch.startDate
		}
		if (patch.endDate !== undefined) {
			this.endDate = patch.endDate
		}
		this.validate()
	}

	/**
	 * Records (or clears) a per-occurrence status deviation. Setting an
	 * occurrence back to `DEFAULT_OCCURRENCE_STATUS` *drops* its override so
	 * the overrides array stays minimal — the exclusion set never holds rows
	 * that match the default.
	 */
	setStatusOverride(occurrenceDate: Date, status: OperationalCostPaymentStatus): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot override status on a deleted OperationalCost')
		}
		const i = this.statusOverrides.findIndex(o => o.occurrenceDate.getTime() === occurrenceDate.getTime())
		if (status === OperationalCost.DEFAULT_OCCURRENCE_STATUS) {
			if (i >= 0) this.statusOverrides.splice(i, 1)
		} else if (i >= 0) {
			this.statusOverrides[i] = { occurrenceDate, status }
		} else {
			this.statusOverrides.push({ occurrenceDate, status })
		}
		this.validate()
	}

	/** End of the occurrence series: explicit `endDate`, or `now` for an open-ended cost. */
	private effectiveEnd(now: Date): Date {
		return this.endDate ?? now
	}

	/** Status for a derived occurrence — the override if one exists, else the default. */
	resolveStatus(occurrenceDate: Date): OperationalCostPaymentStatus {
		return (
			this.statusOverrides.find(o => o.occurrenceDate.getTime() === occurrenceDate.getTime())?.status ??
			OperationalCost.DEFAULT_OCCURRENCE_STATUS
		)
	}

	/**
	 * Strategy 1 — **windowed expansion**. Derives occurrences in `[from, to)`
	 * (bounded by the series) and returns the total count plus only the
	 * requested `page`/`limit` slice, each resolved to its status. At most
	 * `limit` occurrences are materialized regardless of series length.
	 */
	expandOccurrences(input: { from: Date; to: Date; page: number; limit: number; now?: Date }): {
		total: number
		occurrences: OperationalCostOccurrence[]
	} {
		const { total, dates } = occurrenceWindow(
			this.startDate,
			this.effectiveEnd(input.now ?? new Date()),
			this.recurrency,
			input.from,
			input.to,
			input.page,
			input.limit,
		)
		return { total, occurrences: dates.map(occurrenceDate => ({ occurrenceDate, status: this.resolveStatus(occurrenceDate) })) }
	}

	/**
	 * Strategy 2 — **multiplication**. The cost incurred in `[from, to)` is
	 * `(occurrences − cancelled) × amount`: the full derived count, minus the
	 * occurrences excluded by a CANCELLED override. No occurrences are
	 * materialized — counting is O(1) arithmetic. (PAID/UNPAID/OVERDUE are
	 * payment-tracking states; the expense is still incurred, so only
	 * CANCELLED removes it from the total.)
	 */
	incurredCentsBetween(from: Date, to: Date, now?: Date): number {
		const end = this.effectiveEnd(now ?? new Date())
		const count = countOccurrencesInRange(this.startDate, end, this.recurrency, from, to)
		const cancelled = this.statusOverrides.filter(
			o =>
				o.status === OperationalCostPaymentStatus.CANCELLED &&
				o.occurrenceDate.getTime() >= Math.max(from.getTime(), this.startDate.getTime()) &&
				o.occurrenceDate.getTime() < to.getTime() &&
				o.occurrenceDate.getTime() <= end.getTime(),
		).length
		return Math.max(0, count - cancelled) * this.amount.amountCents
	}

	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'OperationalCost already deleted')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface OperationalCost extends OperationalCostProps {}

import { describe, expect, it } from 'bun:test'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount, MonetaryAmountSchema } from './MonetaryAmount'

describe('MonetaryAmount', () => {
	describe('schema validation', () => {
		it('accepts a zero amount (refunds/zero are valid)', () => {
			const m = MonetaryAmountSchema.parse({ amountCents: 0, currency: CurrencyCode.USD })
			expect(m.amountCents).toBe(0)
			expect(m.currency).toBe(CurrencyCode.USD)
		})

		it('accepts a positive amount', () => {
			const m = MonetaryAmountSchema.parse({ amountCents: 12_500, currency: CurrencyCode.BRL })
			expect(m.amountCents).toBe(12_500)
		})

		it('rejects negative amountCents', () => {
			expect(() => MonetaryAmountSchema.parse({ amountCents: -1, currency: CurrencyCode.USD })).toThrow()
		})

		it('rejects negative amountCents (previously allowed in sales readmodel — now enforced globally)', () => {
			expect(() => MonetaryAmountSchema.parse({ amountCents: -500, currency: CurrencyCode.BRL })).toThrow()
		})

		it('rejects non-integer amountCents', () => {
			expect(() => MonetaryAmountSchema.parse({ amountCents: 12.5, currency: CurrencyCode.USD })).toThrow()
		})

		it('rejects unknown currency', () => {
			expect(() => MonetaryAmountSchema.parse({ amountCents: 100, currency: 'XYZ' })).toThrow()
		})
	})

	describe('VO construction', () => {
		it('constructs via new MonetaryAmount()', () => {
			const vo = new MonetaryAmount({ amountCents: 500, currency: CurrencyCode.USD })
			expect(vo.amountCents).toBe(500)
			expect(vo.currency).toBe(CurrencyCode.USD)
		})

		it('throws on invalid input', () => {
			expect(() => new MonetaryAmount({ amountCents: -1, currency: CurrencyCode.USD })).toThrow()
		})

		it('toJSON returns plain object', () => {
			const vo = new MonetaryAmount({ amountCents: 1000, currency: CurrencyCode.USD })
			const json = vo.toJSON()
			expect(json).toEqual({ amountCents: 1000, currency: CurrencyCode.USD })
		})

		it('equals: same values → true', () => {
			const a = new MonetaryAmount({ amountCents: 100, currency: CurrencyCode.USD })
			const b = new MonetaryAmount({ amountCents: 100, currency: CurrencyCode.USD })
			expect(a.equals(b)).toBe(true)
		})

		it('equals: different amountCents → false', () => {
			const a = new MonetaryAmount({ amountCents: 100, currency: CurrencyCode.USD })
			const b = new MonetaryAmount({ amountCents: 200, currency: CurrencyCode.USD })
			expect(a.equals(b)).toBe(false)
		})

		it('equals: different currency → false', () => {
			const a = new MonetaryAmount({ amountCents: 100, currency: CurrencyCode.USD })
			const b = new MonetaryAmount({ amountCents: 100, currency: CurrencyCode.BRL })
			expect(a.equals(b)).toBe(false)
		})
	})
})

/**
 * Dashboard read vocabulary. Each Stat KPI is `{ metric, details? }`; AdditionalCost is its own
 * top-level breakdown. National adds `paymentMethods` (under Stat) and `draftOrders` (under
 * AdditionalCost). Consolidated variants swap money leaves to CurrencyMetric.
 * Generic atoms (Metric/CurrencyMetric/Tally/segmented) come from @shared/schemas.
 */
import { z } from '@bk-dash/core-typescript'
import {
	CurrencyCode,
	CostKind,
	MarketingPlatform,
	AdAttribution,
	DisputeStatus,
	PaymentMethod,
	PaymentStatus,
	OperationalCostFlow,
	OperationalCostRecurrency,
} from '@bk-dash/contracts-typescript/wire/enums'
import { MetricSchema, CurrencyMetricSchema, TallySchema, ConsolidatedTallySchema, segmented } from '../../shared/schemas'

// ---------------------------------------------------------------------------
// Consolidated segmented helper (money leaves → CurrencyMetric)
// ---------------------------------------------------------------------------
const segmentedCurrency = <T extends Record<string, string>>(enumObject: T) =>
	z.object({ total: CurrencyMetricSchema, segments: z.enumRecord(enumObject, CurrencyMetricSchema) })

// ---------------------------------------------------------------------------
// Operational cost item
// ---------------------------------------------------------------------------
export const OperationalCostItemSchema = z.object({
	id: z.string(),
	name: z.string(),
	flow: z.enum(OperationalCostFlow),
	frequency: z.enum(OperationalCostRecurrency),
	amount: z.number(),
	currency: z.enum(CurrencyCode),
	startDate: z.iso.datetime({ offset: true }),
	endDate: z.iso.datetime({ offset: true }).nullable(),
})

// ---------------------------------------------------------------------------
// Stat — each KPI is `{ metric, details? }`. Money KPIs become CurrencyMetric when consolidated;
// ratios/counts (margin, roi, roas, unitsSold) stay Metric. orders/paymentMethods carry count +
// value, so their leaves are Tally.
// ---------------------------------------------------------------------------
export const StatSchema = z.object({
	revenue: z.object({ metric: MetricSchema }),
	profit: z.object({ metric: MetricSchema }),
	margin: z.object({ metric: MetricSchema }),
	averageTicket: z.object({ metric: MetricSchema }),
	unitsSold: z.object({ metric: MetricSchema }),
	roi: z.object({ metric: MetricSchema }),
	roas: z.object({ metric: MetricSchema }),
	costs: z.object({ metric: MetricSchema, details: segmented(CostKind) }),
	productCost: z.object({ metric: MetricSchema, details: z.object({ product: MetricSchema, shipping: MetricSchema }) }),
	fees: z.object({
		metric: MetricSchema,
		details: z.object({ gateway: MetricSchema, checkout: MetricSchema, chargeback: MetricSchema }),
	}),
	ads: z.object({
		metric: MetricSchema,
		details: z.object({
			byPlatform: segmented(MarketingPlatform),
			byType: segmented(AdAttribution),
			tax: MetricSchema,
			cpa: MetricSchema,
		}),
	}),
	orders: z.object({ metric: TallySchema, details: z.object({ generated: TallySchema, paid: TallySchema }) }),
})

const PaymentMethodsStatSchema = z.object({
	metric: TallySchema,
	details: z.object({
		byMethod: z.enumRecord(PaymentMethod, z.object({ total: TallySchema, byStatus: z.enumRecord(PaymentStatus, TallySchema) })),
	}),
})

/** NATIONAL adds the payment-method breakdown as a Stat entry. */
export const StatNationalSchema = StatSchema.extend({ paymentMethods: PaymentMethodsStatSchema })

/** Per-store Stat keyed by StoreIntegrationId (UUID string). Each store mono-currency. */
export const PerStoreStatSchema = z.record(z.string(), StatSchema)

// ---------------------------------------------------------------------------
